from runtime import build, read

def transform(payload, contract):
    """Return the business report described in SPEC.md. Leave caller inputs unchanged."""
    raise NotImplementedError

def load_payload(path):
    return read(path)

def build_component(root, contract):
    return build(root, contract, transform)

def analyze_cfg(config, cfg):
    "Accept the public config and cfg dicts. Return a dict with live_in, live_out, interference, and call_forbidden in their exact public formats. Use predecessor-edge phi inputs, the least liveness fixed point for all blocks, conservative undirected interference, and live-after call clobbers with the stated exception for the call's own definition.\n\nLocal check: Use P with parameter a, one call defining c, and successor Q. Q defines phi x from a on edge P to Q and has an instruction using x and c. With R0 call-clobbered, assert P's live_out set is {'a', 'c'}, Q's live_in set is {'c'}, the interference pairs are a--c and c--x, and only a is forbidden from R0."
    raise NotImplementedError

def allocate(config, cfg, spill_cost, edge_frequency, facts):
    'Accept the original config, cfg, spill costs, and edge frequencies, plus a facts dict containing the analysis fields. Return a dict with status, reason, min_spill, copy_cost, locations, spills, and edge_moves in the public formats. Optimize globally and exactly by spill cost and frequency-weighted phi copies, honor precolors and call constraints with the stated error precedence, and report copies and cycles for the returned allocation.\n\nLocal check: Pass an explicit interference path a--b--c, one register, no precolors or call constraints, and costs 4, 7, and 5 respectively. Assert that b alone is spilled and min_spill is 7. In another fixture pin a and b to the same register while a is call-forbidden there, and assert PRECOLOR_CALL_CLOBBER takes precedence.'
    raise NotImplementedError

