def analyze_cfg(config, cfg):
    """Compute liveness, interference, and call_forbidden per SPEC.md."""
    blocks = {b["id"]: b for b in cfg["blocks"]}
    ids = list(blocks.keys())

    # Precompute per-block facts.
    phi_defs = {}
    defined = {}
    use = {}
    for bid, b in blocks.items():
        pdefs = set()
        dset = set()
        uset = set()
        for phi in b.get("phis", []):
            pdefs.add(phi["def"])
            dset.add(phi["def"])
        for ins in b.get("instructions", []):
            if ins.get("def") is not None:
                dset.add(ins["def"])
            for u in ins.get("uses", []):
                if u not in dset:
                    uset.add(u)
        phi_defs[bid] = pdefs
        defined[bid] = dset
        use[bid] = uset

    # edge_use(B,S): successor S's phi inputs selected by predecessor B.
    def edge_use(pred, succ):
        r = set()
        for phi in blocks[succ].get("phis", []):
            r.add(phi["inputs"][pred])
        return r

    # Least fixed point.
    live_in = {bid: set() for bid in ids}
    live_out = {bid: set() for bid in ids}
    changed = True
    while changed:
        changed = False
        for bid in ids:
            b = blocks[bid]
            out = set()
            for s in b.get("successors", []):
                out |= (live_in[s] - phi_defs[s]) | edge_use(bid, s)
            inn = use[bid] | (out - defined[bid])
            if out != live_out[bid] or inn != live_in[bid]:
                live_out[bid] = out
                live_in[bid] = inn
                changed = True

    # Interference and call_forbidden.
    interference = set()
    call_forbidden = {}
    clobbered = set(config.get("call_clobbered", []))

    def add_pairs(s):
        lst = list(s)
        for i in range(len(lst)):
            for j in range(i + 1, len(lst)):
                a, b = lst[i], lst[j]
                if a != b:
                    interference.add(tuple(sorted((a, b))))

    for bid in ids:
        b = blocks[bid]
        live = set(live_out[bid])
        add_pairs(live)
        for ins in reversed(b.get("instructions", [])):
            d = ins.get("def")
            if ins.get("call"):
                # forbid clobbered regs for live_after except own def
                for v in live:
                    if v != d:
                        for r in clobbered:
                            call_forbidden.setdefault(v, set()).add(r)
            if d is not None:
                for v in live:
                    if v != d:
                        interference.add(tuple(sorted((d, v))))
                live.discard(d)
            for u in ins.get("uses", []):
                live.add(u)
            add_pairs(live)
        add_pairs(live)
        add_pairs(live_in[bid])

    return {
        "live_in": {bid: sorted(live_in[bid]) for bid in ids},
        "live_out": {bid: sorted(live_out[bid]) for bid in ids},
        "interference": sorted(interference),
        "call_forbidden": {v: sorted(rs) for v, rs in call_forbidden.items() if rs},
    }

def allocate(config, cfg, spill_cost, edge_frequency, facts):
    """Globally optimal register allocation per SPEC.md."""
    registers = config["registers"]
    clobbered = set(config.get("call_clobbered", []))
    precolors = config.get("precolors", {})
    interference = set(tuple(sorted(e)) for e in facts["interference"])
    call_forbidden = facts["call_forbidden"]

    variables = list(spill_cost.keys())
    n = len(variables)
    idx = {v: i for i, v in enumerate(variables)}

    # Error precedence: PRECOLOR_CALL_CLOBBER first.
    for v, r in precolors.items():
        if r in call_forbidden.get(v, set()):
            return _unsat("PRECOLOR_CALL_CLOBBER")
    # Then PRECOLOR_INTERFERENCE.
    pinned = list(precolors.items())
    for i in range(len(pinned)):
        for j in range(i + 1, len(pinned)):
            v1, r1 = pinned[i]
            v2, r2 = pinned[j]
            if r1 == r2 and tuple(sorted((v1, v2))) in interference:
                return _unsat("PRECOLOR_INTERFERENCE")

    # Enumerate all assignments: each variable -> register index or spill.
    # Use branch and bound over spill cost (primary) then copy cost (secondary).
    # Number of variables <= 22, registers <= 4 -> 5^22 too large; use DP/ILP via
    # exhaustive search with pruning. We use a recursive search with memo on
    # (position, assignment-so-far) is too big; instead do branch-and-bound.

    # Precompute edge phi moves for copy cost.
    blocks = {b["id"]: b for b in cfg["blocks"]}
    edges = []
    for pred, b in blocks.items():
        for succ in b.get("successors", []):
            phis = blocks[succ].get("phis", [])
            freq = next(e["frequency"] for e in edge_frequency
                        if e["pred"] == pred and e["succ"] == succ)
            edges.append((pred, succ, phis, freq))

    # Forbidden register sets per variable.
    forbidden = {v: set(call_forbidden.get(v, [])) for v in variables}

    # Precolor constraints.
    precolor_reg = {}
    for v, r in precolors.items():
        precolor_reg[v] = registers.index(r)

    best = None  # (spill_cost, copy_cost, assignment)

    # Order variables by spill cost descending for better pruning.
    order = sorted(range(n), key=lambda i: -spill_cost[variables[i]])

    # assignment: list of length n, value in 0..len(registers)-1 or None (spill)
    assignment = [None] * n

    def copy_cost_of(assign):
        total = 0
        for pred, succ, phis, freq in edges:
            for phi in phis:
                src = phi["inputs"][pred]
                dst = phi["def"]
                ls = assign[idx[src]]
                ld = assign[idx[dst]]
                if ls != ld:
                    total += freq
        return total

    def search(pos, spill_sum, assign):
        nonlocal best
        if best is not None and spill_sum > best[0]:
            return
        if pos == n:
            cc = copy_cost_of(assign)
            if best is None or (spill_sum, cc) < (best[0], best[1]):
                best = (spill_sum, cc, assign[:])
            return
        vi = order[pos]
        v = variables[vi]
        # Try registers first (cheaper spill), then spill.
        # Precolor forces a register.
        if v in precolor_reg:
            r = precolor_reg[v]
            if r in forbidden[v]:
                return
            # check interference with already-assigned register vars
            ok = True
            for u in variables:
                ui = idx[u]
                if assign[ui] is not None and assign[ui] == r and u != v:
                    if tuple(sorted((u, v))) in interference:
                        ok = False
                        break
            if ok:
                assign[vi] = r
                search(pos + 1, spill_sum, assign)
                assign[vi] = None
            return
        # Try each register.
        for r in range(len(registers)):
            if r in forbidden[v]:
                continue
            ok = True
            for u in variables:
                ui = idx[u]
                if assign[ui] is not None and assign[ui] == r and u != v:
                    if tuple(sorted((u, v))) in interference:
                        ok = False
                        break
            if ok:
                assign[vi] = r
                search(pos + 1, spill_sum, assign)
                assign[vi] = None
        # Try spill.
        assign[vi] = None
        search(pos + 1, spill_sum + spill_cost[v], assign)
        assign[vi] = None

    search(0, 0, assignment)

    if best is None:
        return _unsat("PRECOLOR_INTERFERENCE")

    min_spill, copy_cost, assign = best
    locations = {}
    spills = []
    for v in variables:
        r = assign[idx[v]]
        if r is None:
            locations[v] = "spill:" + v
            spills.append(v)
        else:
            locations[v] = "reg:" + registers[r]

    edge_moves = _edge_moves(blocks, edges, locations)

    return {
        "status": "ALLOCATED",
        "reason": None,
        "min_spill": min_spill,
        "copy_cost": copy_cost,
        "locations": locations,
        "spills": sorted(spills),
        "edge_moves": edge_moves,
    }


def _unsat(reason):
    return {
        "status": "UNSAT_PRECOLOR",
        "reason": reason,
        "min_spill": None,
        "copy_cost": None,
        "locations": {},
        "spills": [],
        "edge_moves": [],
    }


def _edge_moves(blocks, edges, locations):
    from graphlib import TopologicalSorter, CycleError
    rows = []
    for pred, succ, phis, freq in edges:
        moves = []
        deps = {}
        for phi in phis:
            src = phi["inputs"][pred]
            dst = phi["def"]
            left = locations[src]
            right = locations[dst]
            if left == right:
                continue
            moves.append({
                "definition": dst,
                "source": src,
                "from_location": left,
                "to_location": right,
            })
            deps.setdefault(left, set())
            deps.setdefault(right, set()).add(left)
        try:
            list(TopologicalSorter(deps).static_order())
            cycle = False
        except CycleError:
            cycle = True
        rows.append({"pred": pred, "succ": succ, "moves": moves, "cycle": cycle})
    return rows

