import unittest

from engines.analysis.cfg_facts import analyze_cfg
from engines.analysis.weighted_allocation import allocate


def _run(request):
    from engines.analysis.engine import transform
    return transform({"request": request}, {})


class TestCfgFacts(unittest.TestCase):
    def test_liveness_and_interference(self):
        # SPEC.md local check: P with param a, call defining c, successor Q.
        config = {"registers": ["R0"], "call_clobbered": ["R0"], "precolors": {}}
        cfg = {
            "entry": "P",
            "parameters": ["a"],
            "blocks": [
                {"id": "P", "successors": ["Q"], "phis": [],
                 "instructions": [{"id": "call", "uses": [], "def": "c", "call": True}]},
                {"id": "Q", "successors": [], "phis": [{"def": "x", "inputs": {"P": "a"}}],
                 "instructions": [{"id": "u", "uses": ["x", "c"], "def": None, "call": False}]},
            ],
        }
        f = analyze_cfg(config, cfg)
        self.assertEqual(set(f["live_out"]["P"]), {"a", "c"})
        self.assertEqual(set(f["live_in"]["Q"]), {"c"})
        self.assertEqual({tuple(sorted(e)) for e in f["interference"]},
                         {("a", "c"), ("c", "x")})
        self.assertEqual(f["call_forbidden"], {"a": ["R0"]})


class TestAllocation(unittest.TestCase):
    def test_min_spill_path(self):
        config = {"registers": ["R0"], "call_clobbered": [], "precolors": {}}
        cfg = {"entry": "E", "parameters": ["a", "b", "c"],
               "blocks": [{"id": "E", "successors": [], "phis": [], "instructions": []}]}
        facts = {"interference": [["a", "b"], ["b", "c"]], "call_forbidden": {}}
        sc = {"a": 4, "b": 7, "c": 5}
        r = allocate(config, cfg, sc, [], facts)
        self.assertEqual(r["min_spill"], 7)
        self.assertEqual(r["spills"], ["b"])

    def test_precolor_call_clobber_precedence(self):
        config = {"registers": ["R0"], "call_clobbered": ["R0"],
                  "precolors": {"a": "R0", "b": "R0"}}
        cfg = {"entry": "E", "parameters": ["a", "b"],
               "blocks": [{"id": "E", "successors": [], "phis": [], "instructions": []}]}
        facts = {"interference": [], "call_forbidden": {"a": ["R0"]}}
        sc = {"a": 1, "b": 1}
        r = allocate(config, cfg, sc, [], facts)
        self.assertEqual(r["status"], "UNSAT_PRECOLOR")
        self.assertEqual(r["reason"], "PRECOLOR_CALL_CLOBBER")

    def test_frequency_weighted_copy_cost(self):
        # SPEC.md additional example: E->P,Q->M; a/b pinned R0/R1.
        request = {
            "config": {"registers": ["R0", "R1"], "call_clobbered": [],
                       "precolors": {"a": "R0", "b": "R1"}},
            "cfg": {
                "entry": "E", "parameters": ["a", "b"],
                "blocks": [
                    {"id": "E", "successors": ["P", "Q"], "phis": [], "instructions": []},
                    {"id": "P", "successors": ["M"], "phis": [], "instructions": []},
                    {"id": "Q", "successors": ["M"], "phis": [], "instructions": []},
                    {"id": "M", "successors": [], "phis": [
                        {"def": "x", "inputs": {"P": "a", "Q": "b"}},
                        {"def": "y", "inputs": {"P": "b", "Q": "a"}},
                    ], "instructions": [
                        {"id": "use", "uses": ["x", "y"], "def": None, "call": False}]},
                ],
            },
            "spill_cost": {"a": 1, "b": 1, "x": 1, "y": 1},
            "edge_frequency": [
                {"pred": "E", "succ": "P", "frequency": 1},
                {"pred": "E", "succ": "Q", "frequency": 1},
                {"pred": "P", "succ": "M", "frequency": 1},
                {"pred": "Q", "succ": "M", "frequency": 3},
            ],
        }
        r = _run(request)
        self.assertEqual(r["status"], "ALLOCATED")
        self.assertEqual(r["min_spill"], 0)
        self.assertEqual(r["copy_cost"], 2)
        self.assertEqual(r["locations"]["x"], "reg:R1")
        self.assertEqual(r["locations"]["y"], "reg:R0")


